import'zone.js';import'@angular/compiler';import{Component}from'@angular/core';import{bootstrapApplication}from'@angular/platform-browser';class App{name='';choice='a';count=0;modal=false;route(e){e.preventDefault();history.pushState({},'', '/angular/details')}}Component({selector:'app-root',standalone:true,template:`<main><h1>Angular inventory</h1><p>Important compatibility content</p><a href="/angular/details" (click)="route($event)">Details route</a><label>Name<input [value]="name" (input)="name=$any($event.target).value"></label><label>Choice<select [value]="choice" (change)="choice=$any($event.target).value"><option value="a">Alpha</option><option value="b">Beta</option></select></label><output>Name state: {{name}}; choice state: {{choice}}; count: {{count}}</output><button (click)="count=count+1">Increment</button><button (click)="modal=!modal">Toggle dialog</button>@if(modal){<div role="dialog"><p>Dialog content</p><button (click)="modal=false">Close dialog</button></div>}<button hidden>Hidden action</button><button disabled>Disabled action</button></main>`})(App);bootstrapApplication(App);